/// <summary>
/// Controller class for the Sales order bundling report
/// </summary>
class METSalesOrderShipmentBundlingReportController extends SrsReportRunController
{
    METSalesOrderShipmentBundlingReportContract contract;
    METOrderShipmentBundlingReportHeaderTmp     bundlingReportHeaderTmp;

}

Method.Source:
/// <summary>
/// Handles the logic of priniting the report
/// </summary>
/// <param name = "_args">controller args</param>
static void main(Args _args)
{
    METSalesOrderShipmentBundlingReportController controller;

    controller = new METSalesOrderShipmentBundlingReportController();
    controller.parmReportName(ssrsReportStr(METSalesOrderShipmentBundlingReport, NewReport));
    controller.parmDialogCaption("Sales order Bundling report");
    controller.parmArgs(_args);

    METSalesOrderShipmentBundlingReportContract contract = controller.parmReportContract().parmRdpContract();

    controller.startOperation();
}

protected METSalesOrderShipmentBundlingReportContract parmContract()
{
    if (!contract)
    {
        contract = this.parmReportContract().parmRdpContract() as METSalesOrderShipmentBundlingReportContract;
    }
    return contract;
}

